const issues = [974, 975, 976, 977, 978];
const triageRuns = await runs.all(issues.map((number) => ({
  key: `issue-${number}`,
  agent: 'triage',
  task: `Review open GitHub issue #${number} in chrisdoc/hevy-mcp as an independent read-only diagnosis lane. Work in /root/hevy-mcp-issue-fixes, a clean feature worktree based on origin/main. Retrieve the full issue and comments using the configured GitHub integration when available, otherwise use read-only gh commands. Inspect current main code, CONTEXT.md if present, and relevant ADRs. Follow the diagnosing-bugs skill: build a tight red-capable reproduction for the reported symptom before settling on a theory, minimize it, rank 3–5 falsifiable hypotheses, and identify the correct regression-test seam. For a closed or already-fixed historical issue, explicitly justify skipping deeper phases rather than inventing work. Do not edit files, commit, push, comment, label, close, or otherwise mutate GitHub. Redact all secrets and sensitive issue content. Return a concise diagnosis with classification, symptom, reproduction/result, minimized case, ranked hypotheses, likely root cause and confidence, affected paths, regression-test recommendation, blockers, and recommended fix.`
}))));
const findings = triageRuns.map((run, index) => `=== TRIAGE ISSUE #${issues[index]} ===\n${run.output ?? String(run)}`).join('\n\n');
const planRun = await runs.run('synthesis', {
  agent: 'reviewer',
  task: `Act as the synthesis gate for a fix PR. Five independent read-only diagnoses for currently open issues in chrisdoc/hevy-mcp are below. Inspect /root/hevy-mcp-issue-fixes and verify the strongest claims against source and tests before deciding. Select at most one coherent, high-confidence bug family for a single focused PR; related issue numbers may be grouped, but do not combine unrelated fixes. Prefer a reproducible issue with a real regression-test seam. If evidence is insufficient or no safe fix is justified, say NO_SAFE_FIX. Do not edit, commit, push, or change GitHub. Return a concrete implementation plan with selected issue numbers, root cause, scope, regression-test plan, validation plan, PR title/body, and risks.\n\nTRIAGE FINDINGS:\n${findings}`,
  worktree: false
});
const plan = planRun.output ?? String(planRun);
const implementationRun = await runs.run('implementation', {
  agent: 'worker',
  task: `You are the only mutation-capable implementation worker. Work in /root/hevy-mcp-issue-fixes on branch fix/github-issues-review, based on origin/main. The synthesis plan and supporting diagnoses are below.\n\nSYNTHESIS PLAN:\n${plan}\n\nSUPPORTING DIAGNOSES:\n${findings}\n\nIf the synthesis says NO_SAFE_FIX, do not edit, commit, push, or create a PR; report no safe fix. Otherwise implement only the approved focused scope. Read AGENTS.md, CONTRIBUTING.md, docs/test-lanes.md, and relevant package/topology guidance before changing code. Follow the diagnosing-bugs discipline: add the regression test at the correct seam before the fix, run it red if possible, implement the smallest fix, run it green, and rerun the original red-capable reproduction. Use the repository's mise-pinned Node/npm commands and keep secrets out of output. Add a non-empty Changeset for every affected shipped package and transitive consumer required by repository/topology.json; use an empty changeset only if the diff truly has no release trigger. Run the narrow relevant lane plus the required PR baseline as practical, including check:changeset. Keep the diff focused and do not modify unrelated existing work. Commit with a Conventional Commit message, push the feature branch, and open a pull request against main using the configured GitHub integration; if unavailable, use gh as the documented fallback. Do not merge or close issues. Report changed files, exact validation commands/results, commit SHA, PR URL, and residual risks. Never claim success for a command you did not run.`,
  worktree: false
});
return {
  issueCount: issues.length,
  triageFindings: triageRuns.map((run, index) => ({ issue: issues[index], output: run.output ?? String(run) })),
  synthesis: plan,
  implementation: implementationRun.output ?? String(implementationRun)
};

